    }","receipt":"PYzpFY94CoUFtFfAUx5fawfHUDXael9MpPLZK1MUx0U"},{"start_line":311,"end_line":331,"symbol":"FindPathRefs","text":"    public IReadOnlyList<RefMention> FindPathRefs(string indexedPath, PathScope? scope = null)
