    {
        var rules = new List<Rule>();
        foreach (string raw in lines)
        {
            string line = raw.TrimEnd();
            if (line.Length == 0 || line.StartsWith('#'))
            {
                continue;
            }

            bool negate = false;
            if (line.StartsWith('!'))
            {
                negate = true;
                line = line[1..];
            }

            bool dirOnly = line.EndsWith('/');
            if (dirOnly)
            {
                line = line[..^1];
            }

            bool anchored = line.StartsWith('/');
            if (anchored)
            {
                line = line[1..];
            }

            // A slash anywhere (other than a trailing one) anchors the pattern.
            if (line.Contains('/'))
            {
                anchored = true;
            }

            if (line.Length == 0)
            {
                continue;
            }

            rules.Add(new Rule(GlobPattern.ToRegex(line), negate, dirOnly, anchored));
        }

        return new GitignoreMatcher(rules);
    }","receipt":"RmMKj7oLvqZNhLxXRtoCKd2LoDSkbpOAHmoZ54hNub0"},{"start_line":73,"end_line":73,"symbol":"FromGlobs","text":"    public static GitignoreMatcher FromGlobs(IEnumerable<string> globs) => Parse(globs);","receipt":"bqW7fbs88qR6ITIjFbYP5yQGMjKawInYikweONq5p-U"},{"start_line":85,"end_line":108,"symbol":"Match","text":"    public bool? Match(string relativePath, bool isDirectory)
