    {
        var rules = new List<Rule>();
        foreach (string raw in lines)
        {
            string line = raw.TrimEnd();
            if (line.Length == 0 || line.StartsWith('#'))
            {
                continue;
            }

            bool negate = false;
            if (line.StartsWith('!'))
            {
                negate = true;
                line = line[1..];
            }

            bool dirOnly = line.EndsWith('/');
            if (dirOnly)
            {
                line = line[..^1];
            }

            bool anchored = line.StartsWith('/');
            if (anchored)
            {
                line = line[1..];
            }

            // A slash anywhere (other than a trailing one) anchors the pattern.
            if (line.Contains('/'))
            {
                anchored = true;
            }

            if (line.Length == 0)
            {
                continue;
            }

            rules.Add(new Rule(GlobPattern.ToRegex(line), negate, dirOnly, anchored));
        }

        return new GitignoreMatcher(rules);
    }","receipt":"RmMKj7oLvqZNhLxXRtoCKd2LoDSkbpOAHmoZ54hNub0"},{"start_line":73,"end_line":73,"symbol":"FromGlobs","text":"    public static GitignoreMatcher FromGlobs(IEnumerable<string> globs) => Parse(globs);","receipt":"bqW7fbs88qR6ITIjFbYP5yQGMjKawInYikweONq5p-U"},{"start_line":85,"end_line":108,"symbol":"Match","text":"    public bool? Match(string relativePath, bool isDirectory)
    {
        string normalized = relativePath.Replace('\\', '/').TrimStart('/');
        string basename = normalized.Length == 0
            ? string.Empty
            : normalized[(normalized.LastIndexOf('/') + 1)..];

        bool? ignored = null;
        foreach (Rule rule in _rules)
        {
            if (rule.DirOnly && !isDirectory)
            {
                continue;
            }

            string target = rule.Anchored ? normalized : basename;
            if (rule.Regex.IsMatch(target))
            {
                ignored = !rule.Negate;
            }
        }

        return ignored;
    }","receipt":"poecPGQQbN8_Iqgm0U8q_CejP0TmllNRO6zn2VO_EOs"}]},{"path":"docs/decisions/0004-data-model-and-contracts.md","kind":"doc","score":0.2225,"content_tokens":713,"projected_read_tokens":0,"estimated_tokens":804,"file_tokens":910,"hash":"bec0040858dc","reasons":["fts","mentions:repoctx.config.json","mentions:src/RepoContext.Core/Storage/IndexSchema.cs","mentioned-by:docs/decisions/README.md","penalty:doc"],"spans":[{"start_line":13,"end_line":25,"text":"## SQLite schema (`.repoctx/index.db`, WAL)

- `meta(key TEXT PK, value TEXT)` — `schema_version`, `tool_version`,
  `config_hash`, `indexed_at_utc` (the only timestamp; in stats, not results),
  `file_count`, `chunk_count`.
- `files(id, path UNIQUE, kind, language, size_bytes, line_count, content_hash)`.
- `chunks(id, file_id → files ON DELETE CASCADE, kind, start_line, end_line, heading, content)`.
- `chunks_fts` — FTS5 (`content`, `unicode61 remove_diacritics 2`), `rowid = chunks.id`.

`kind`/`language`/`chunk.kind` are stored lowercase (`source`, `typescript`,
`preamble`, …). A separate `IndexSchema.Version` (currently 1) governs on-disk
rebuilds and is distinct from the JSON `schema_version`.
