namespace RepoContext.Core.Scanning;

/// <summary>
/// A gitignore-style path matcher. Used for <c>.gitignore</c>,
/// <c>.repoctxignore</c>, the config <c>exclude</c> list and
/// <c>sensitiveFiles</c>. Paths are relative to the repository root, use
/// <c>/</c> separators, and directory pruning during traversal handles
/// descendant semantics.
/// </summary>
public sealed class GitignoreMatcher
{
    private readonly record struct Rule(Regex Regex, bool Negate, bool DirOnly, bool Anchored);

    private readonly IReadOnlyList<Rule> _rules;

    private GitignoreMatcher(IReadOnlyList<Rule> rules) => _rules = rules;

    /// <summary>An empty matcher that ignores nothing.</summary>","receipt":"-pisFqj73Or82AqpLy_HeZvXGyidcPfu9_7AnrIr14E"},{"start_line":24,"end_line":69,"symbol":"Parse","text":"    public static GitignoreMatcher Parse(IEnumerable<string> lines)
    {
        var rules = new List<Rule>();
        foreach (string raw in lines)
        {
            string line = raw.TrimEnd();
            if (line.Length == 0 || line.StartsWith('#'))
            {
                continue;
            }

            bool negate = false;
            if (line.StartsWith('!'))
            {
                negate = true;
                line = line[1..];
            }

            bool dirOnly = line.EndsWith('/');
            if (dirOnly)
            {
                line = line[..^1];
            }

            bool anchored = line.StartsWith('/');
            if (anchored)
            {
                line = line[1..];
            }

            // A slash anywhere (other than a trailing one) anchors the pattern.
            if (line.Contains('/'))
            {
                anchored = true;
            }

            if (line.Length == 0)
            {
                continue;
            }

            rules.Add(new Rule(GlobPattern.ToRegex(line), negate, dirOnly, anchored));
        }

        return new GitignoreMatcher(rules);
    }","receipt":"RmMKj7oLvqZNhLxXRtoCKd2LoDSkbpOAHmoZ54hNub0"}]},{"path":"src/RepoContext.Core/Configuration/RepoctxConfig.cs","kind":"source","score":0.3172,"content_tokens":37,"projected_read_tokens":0,"estimated_tokens":154,"file_tokens":1928,"hash":"5f66fff20218","reasons":["fts","symbol:RespectGitignore","symbol:Exclude","imported-by:src/RepoContext.Core/Scanning/FileScanner.cs","mentioned-by:docs/cost-efficiency-implementation-plan.md","imported-by:src/RepoContext.Core/Configuration/Initializer.cs","graph:+63","mentions:repoctx.config.json"],"spans":[{"start_line":25,"end_line":25,"symbol":"Exclude","text":"    public IReadOnlyList<string> Exclude { get; init; } = [];","receipt":"I1UbnUbnPX51N5aofyQeGfnB1tQFWky5kop22NWenXc"},{"start_line":27,"end_line":27,"symbol":"RespectGitignore","text":"    public bool RespectGitignore { get; init; } = true;","receipt":"PIfJ_Xog0MQHmFveZRMYH0S5MLUTlION_RIKCZyap5Y"}]},{"path":"repocontext-produktdoku.md","kind":"doc","score":0.2844,"content_tokens":884,"projected_read_tokens":0,"estimated_tokens":1048,"file_tokens":3897,"hash":"ca92b73b65ed","reasons":["fts","mentions:README.md","mentioned-by:docs/decisions/0017-whole-repository-coverage.md","mentioned-by:docs/build-prompt.md","mentions:repoctx.config.json","mentions:tests/fixtures/sample-cs/Services/UserService.cs","mentions:tests/fixtures/sample-ts/src/auth/__tests__/login.test.ts","mentions:tests/fixtures/sample-ts/src/auth/permissions.ts","mentions:tests/fixtures/sample-ts/src/middleware.ts","mentioned-by:docs/decisions/0003-source-of-truth.md","penalty:doc"],"spans":[{"start_line":46,"end_line":71,"text":"## 3. Lösung

RepoContext baut einen lokalen, deterministischen Index des Projekts auf: Projektstruktur, wichtige Dateien, Klassen und Funktionen, API-Routen, Abhängigkeiten zwischen Dateien, Tests, Konfigurationen sowie README- und Dokumentationsinhalte.

AI Agents fragen diesen Index über CLI oder MCP ab:

```
$ repoctx context "Ich möchte die Login-Logik ändern"

Relevante Dateien (Top 4 von 1'243 indexierten):
 1. src/auth/login.ts        0.92  Symbol: loginUser · Volltext: login
    → loginUser(credentials: Credentials): Promise<Session>  [Z. 12–48]
    → Tests: src/auth/__tests__/login.test.ts
 2. src/auth/session.ts      0.81  wird von login.ts importiert
 3. src/middleware.ts        0.64  importiert session.ts
 4. src/auth/permissions.ts  0.58  Symbol: checkPermission

Budget: 4 Dateien · ~1'400 geschätzte Tokens
```

Der Agent erhält kompakten, begründeten Kontext statt ein ganzes Repository.

**Wichtige Abgrenzung gegenüber v1:** Die Ausgabe besteht ausschliesslich aus Fakten, die aus dem Index ableitbar sind (Dateien, Symbole, Kanten, Tests, Begründungen). Generierte Prosa-Zusammenfassungen («Die Authentifizierung läuft über JWT») gibt es nicht – dafür wäre ein LLM nötig. Prosa-artige Hinweise stammen, wo vorhanden, aus echten Quellen (README, Docstrings) und werden als Zitat mit Fundstelle ausgegeben.

---
","receipt":"GkwVU22ZUsNUrLTF7pduZYjyl2_peY8qhGbfP8x0ZBk"},{"start_line":127,"end_line":138,"text":"## 7. Tokenverbrauch

RepoContext selbst verursacht keinen Tokenverbrauch. Tokens entstehen erst, wenn ein Agent oder LLM Text verarbeitet:

* RepoContext liest Dateien lokal → keine Tokens
* RepoContext erstellt und durchsucht den Index → keine Tokens
* RepoContext gibt 20 Zeilen Kontext an den Agent → diese 20 Zeilen können Tokens verursachen

Der Nutzen: Der Agent muss nicht 50 Dateien lesen, sondern bekommt nur die relevanten Informationen – innerhalb eines konfigurierbaren Token-Budgets.

---
","receipt":"GeSpm-bPJxb0aqUm2jdLOd_4lDaezET_9C2J_gXJd-o"},{"start_line":139,"end_line":150,"text":"## 8. Datenschutz

RepoContext sendet standardmässig keine Repository-Daten an externe Dienste und enthält im Kern keine Telemetrie.

**Wichtige, ehrliche Einschränkung:** RepoContext kann verhindern, dass das eigene Tool Daten verschickt. Es kann nicht verhindern, dass ein externer AI Agent die erhaltenen Ausschnitte an einen AI-Anbieter sendet.

Für maximale Sicherheit wird empfohlen: lokales oder selfhosted RepoContext, interner Agent, lokales oder unternehmenseigenes LLM, `.repoctxignore` für sensible Dateien.

Zusätzlich: Der Index selbst (`.repoctx/`) enthält Code-Ausschnitte und ist ein sensibles Artefakt – er wird bei `repoctx init` automatisch in `.gitignore` eingetragen. Dateien aus `.repoctxignore` und `sensitiveFiles` werden weder inhaltlich noch als Pfad indexiert.

---
