  return (request) => {
    let lastError;
    for (const from of paths) {
      try {
        return requireResolve(request, { paths: [from] });
      } catch (error) {
        lastError = error;
      }
    }

    throw lastError ?? new Error(`Cannot find module '${request}'`);
