}","receipt":"HBhJTsCFmLqh1YzsphpUOvR9q93Eo2AXeQe9UMC81U0"},{"start_line":118,"end_line":163,"symbol":"resolveBinary","text":"function resolveBinary({ process: processLike, resolve }) {
  const target = targetFor(processLike.platform, processLike.arch);
