  if (isMuslLinux(processLike)) {
    return {
      ok: false,
      reason: "musl",
      message:
        "repoctx ships self-contained binaries built against glibc, and this looks like a " +
        "musl-based Linux (Alpine). Install the .NET tool on a runtime that matches your libc " +
